<?php
require_once __DIR__.'/config.php';require_login();$pageTitle='Ask a question';$errors=[];$subjects=$pdo->query('SELECT id,name FROM subjects ORDER BY name')->fetchAll();
if(is_post()){verify_csrf();$title=posted_string('title',180);$body=posted_string('body',5000);$subject=valid_id($_POST['subject_id']??0);if(mb_strlen($title)<8)$errors[]='Question title must be at least 8 characters.';if(mb_strlen($body)<20)$errors[]='Explain your question in at least 20 characters.';if(!$subject)$errors[]='Choose a subject.';if(!$errors){$stmt=$pdo->prepare("INSERT INTO questions(user_id,subject_id,title,body,status) VALUES(?,?,?,?, 'visible')");$stmt->execute([current_user()['id'],$subject,$title,$body]);set_flash('success','Your question has been posted.');redirect('question.php?id='.$pdo->lastInsertId());}}
require __DIR__.'/includes/header.php';?>
<section class="page-hero"><div class="container"><span class="eyebrow">ASK THE COMMUNITY</span><h1>What are you stuck on?</h1><p>Give your question a clear title and enough context for another student to help.</p></div></section><div class="page-content"><div class="container"><form class="form-card" method="post"><?= csrf_field() ?><?php if($errors): ?><div class="alert alert-error"><ul><?php foreach($errors as $err): ?><li><?= e($err) ?></li><?php endforeach; ?></ul></div><?php endif; ?><div class="form-group"><label for="title">Question title</label><input id="title" name="title" maxlength="180" value="<?= e($_POST['title']??'') ?>" required placeholder="e.g. Why does binary search require sorted data?"></div><div class="form-group"><label for="subject_id">Subject</label><select id="subject_id" name="subject_id" required><option value="">Choose a subject</option><?php foreach($subjects as $s): ?><option value="<?= (int)$s['id'] ?>"><?= e($s['name']) ?></option><?php endforeach; ?></select></div><div class="form-group"><label for="body">Details</label><textarea id="body" name="body" required maxlength="5000" placeholder="What have you tried? Where exactly are you stuck?"><?= e($_POST['body']??'') ?></textarea></div><button class="btn btn-primary">Post question</button> <a class="btn btn-outline" href="forum.php">Cancel</a></form></div></div><?php require __DIR__.'/includes/footer.php';?>
